document.addEventListener('click',e=>{const tab=e.target.closest('[data-tab]');if(tab){active=tab.dataset.tab;renderTabs();renderOptions();return;}const choice=e.target.closest('[data-choice]');if(choice){choose(active,choice.dataset.choice);return;}});
$('#suggestBtn').addEventListener('click',suggest);
$('#randomBtn').addEventListener('click',()=>randomize(active));
$('#shuffleBtn').addEventListener('click',()=>{tabs.forEach(t=>randomize(t.id));showToast('A fresh little surprise, just for you!');});
$('#poseBtn').addEventListener('click',()=>{pose++;drawAvatar();$('#avatarName').textContent=['Luna','Mira','Cleo','Sage'][pose%4];showToast('Meet your muse in a new pose ✧');});
$('#saveBtn').addEventListener('click',saveLook);
$('#submitBtn').addEventListener('click',openResults);
$('#wardrobeLink').addEventListener('click',e=>{e.preventDefault();wardrobe();});
document.querySelector('.nav a[href="#how"]').addEventListener('click',e=>{e.preventDefault();showToast('Pick a look, bottom, detail & palette. Match the quest clues for a higher score!');});
$('#closeModal').addEventListener('click',()=>{const wasResult=modalMode==='result';$('#resultModal').classList.remove('show');if(wasResult){questIndex=(questIndex+1)%quests.length;questDone=false;renderQuest();showToast('A new style quest is waiting for you ✦');}});
$('#resultModal').addEventListener('click',e=>{if(e.target.id==='resultModal')$('#resultModal').classList.remove('show');});
document.addEventListener('keydown',e=>{if(e.key==='Escape')$('#resultModal').classList.remove('show');});
refresh();

