71: function refresh(){renderTabs();renderOptions();renderQuest();renderHeader();drawAvatar();}
72: function choose(category,id){state[category]=id;renderOptions();renderTasks();drawAvatar();}
73: function randomize(category){const list=catalog[category];let next=list[Math.floor(Math.random()*list.length)].id;if(list.length>1&&next===state[category])next=list[(list.findIndex(x=>x.id===next)+1)%list.length].id;choose(category,next);}
74: function suggest(){state={...state,...quest().target};active='look';refresh();showToast('Muse picked a look for this little moment ✦');}
75: function openResults(){const t=quest().target;const keys=['look','bottom','extra','palette'];const hits=keys.filter(k=>state[k]===t[k]).length;const score=Math.min(100,46+Math.round(hits*13.5));const reward=questDone?0:30;questDone=true;coins+=reward;completed+=reward?1:0;renderHeader();$('#resultArt').textContent=hits===4?'✨':hits>=2?'🌷':'🪻';$('#resultTitle').textContent=hits===4?'A perfect little match!':hits>=2?'A lovely little look!':'Your own kind of magic!';$('#resultText').textContent=reward?`You matched ${hits} of the four style clues. Your look has its own lovely point of view — and you earned ${reward} muse coins for finishing today's quest.`:`You matched ${hits} of the four style clues. Today's reward has already been collected — try another combination or save this look!`;
