88: document.querySelector('.nav a[href="#how"]').addEventListener('click',e=>{e.preventDefault();showToast('Pick a look, bottom, detail & palette. Match the quest clues for a higher score!');});
89: $('#closeModal').addEventListener('click',()=>{const wasResult=modalMode==='result';$('#resultModal').classList.remove('show');if(wasResult){questIndex=(questIndex+1)%quests.length;questDone=false;renderQuest();showToast('A new style quest is waiting for you ✦');}});
